//! Vectors for the data/arithmetic side of mask, laid, BAT, BATT and PSC, generated by
//! `scripts/cpp_vectors/iop_data_vectors.cpp`.

use std::collections::HashMap;
use std::rc::Rc;

use fp_core::chain::public::PublicBytes;
use fp_core::code::code::Code;
use fp_core::field::ext::{F, E};
use fp_core::iop::bat;
use fp_core::iop::batt::{batt_claim, batt_k_col, batt_masks, batt_row, TensorRow};
use fp_core::iop::laid::{
    laid_block_ok, laid_form, laid_ok, laid_tensor, IndexWeights, LaidBlock, LaidMatrix,
};
use fp_core::iop::mask::{receipt_for_a_test, MaskLedger, MaskTerm, SendAccess};
use fp_core::iop::psc::{psc_masks, psc_rows, psc_vars, KeptTerm, PscOutput};
use fp_core::iop::relation::{Codes, OracleShape, Part, Row, Statement};
use fp_core::iop::summand::{SumClaim, Summand};

const VECTORS: &str = include_str!("../../fixtures/iop_data_vectors.txt");

fn ev(s: u64, i: u32) -> E {
    E([
        F(s * 101 + i as u64 * 3 + 1),
        F(s * 211 + i as u64 * 5 + 2),
        F(s * 307 + i as u64 * 7 + 3),
    ])
}
fn fv(s: u64, i: u32) -> F {
    F(s * 401 + i as u64 * 11 + 1)
}
fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}
fn e(s: &str) -> E {
    let p: Vec<&str> = s.split(',').collect();
    assert_eq!(p.len(), 3, "E {}", s);
    E([
        F(u64::from_str_radix(p[0], 16).unwrap()),
        F(u64::from_str_radix(p[1], 16).unwrap()),
        F(u64::from_str_radix(p[2], 16).unwrap()),
    ])
}
fn es(s: &str) -> Vec<E> {
    if s == "-" {
        return Vec::new();
    }
    s.split(';').map(e).collect()
}
fn mask_term(s: &str) -> (u32, u32, E) {
    let (a, bcoeff) = s.split_once(',').unwrap();
    let (b, coeff) = bcoeff.split_once(',').unwrap();
    (a.parse().unwrap(), b.parse().unwrap(), e(coeff))
}

#[test]
fn iop_data_vectors_match_the_cpp_reference() {
    let mut lines = 0usize;
    let mut mask_i = 0usize;
    let mut bat_k = 0u32;
    let mut bat_gr: Option<fp_core::iop::relation::GroupRow> = None;
    let mut batt_rows: Vec<TensorRow> = Vec::new();
    let mut psc_out: Option<PscOutput> = None;

    for line in VECTORS.lines() {
        lines += 1;
        let tag = line.split_whitespace().next().unwrap();
        let kv = fields(line);
        match tag {
            "MASK_START" => {
                let mut ledger = MaskLedger::new(receipt_for_a_test(3, 0, 9, 2, 2));
                assert_eq!(ledger.left(), kv["left"].parse::<u32>().unwrap());
                let mut taken = Vec::new();
                for _ in 0..4 {
                    let slot = ledger.take();
                    let left = ledger.left();
                    taken.push((slot, left));
                }
                // The SLOT lines follow; compare them from the stored slots.
                let mut idx = 0usize;
                for l in VECTORS.lines().skip(lines) {
                    let t = l.split_whitespace().next().unwrap();
                    if t == "MASK_END" {
                        break;
                    }
                    let k = fields(l);
                    assert_eq!(taken[idx].0.oracle(), k["oracle"].parse::<u32>().unwrap());
                    assert_eq!(taken[idx].0.index(), k["index"].parse::<u32>().unwrap());
                    assert_eq!(taken[idx].1, k["left"].parse::<u32>().unwrap());
                    idx += 1;
                }
                ledger.close();
                assert_eq!(ledger.left(), 0);
                mask_i = idx;
            }
            "SLOT" | "MASK_END" => {}
            "LAID_BLOCK" => {
                let b = laid_block();
                assert!(laid_block_ok(&b, 2, 2));
                assert_eq!(PublicBytes::public_fault(&b), None);
            }
            "LAID_BAD" => {
                let mut bad = laid_block();
                bad.first_row = 1;
                assert_eq!(laid_block_ok(&bad, 2, 2), kv["ok"] == "1");
            }
            "LAID_OK" => {
                let mut m = LaidMatrix { size_i: 2, size_c: 2, blocks: Vec::new() };
                m.blocks.push(laid_block());
                assert_eq!(laid_ok(&[m], 2, 2), kv["ok"] == "1");
            }
            "LAID_T" => {
                let t = laid_tensor(&laid_block(), 2, 2, &on_i(), &on_c(), ev(1, 2));
                assert_eq!(t.vars(), kv["vars"].parse::<u32>().unwrap());
                let want = es(kv["at"]);
                for (j, w) in want.iter().enumerate() {
                    assert_eq!(t.at(j as u64), *w, "laid at {}", j);
                }
                let mut pairs = Vec::new();
                for i in 0..t.vars() {
                    if !t.picks(i) {
                        pairs.push(t.lo(i));
                        pairs.push(t.hi(i));
                    }
                }
                assert_eq!(pairs, es(kv["pairs"]));
            }
            "LAID_ADD" => {
                let t = laid_tensor(&laid_block(), 2, 2, &on_i(), &on_c(), ev(1, 2));
                let want = es(kv["out"]);
                let mut got = vec![E::zero(); want.len()];
                t.add_to_simple(&mut got);
                assert_eq!(got, want);
            }
            "LAID_W" => {
                let w = laid_tensor(
                    &laid_block(),
                    2,
                    2,
                    &IndexWeights::written(Rc::new(vec![ev(2, 0), ev(2, 1), ev(2, 2), ev(2, 3)])),
                    &IndexWeights::powers(ev(3, 0), 1),
                    ev(3, 1),
                );
                assert_eq!(w.vars(), kv["vars"].parse::<u32>().unwrap());
                assert_eq!(w.dense_vars.len(), kv["dense"].parse::<usize>().unwrap());
                for (j, want) in es(kv["at"]).iter().enumerate() {
                    assert_eq!(w.at(j as u64), *want);
                }
            }
            "LAID_FORM" => {
                let f = laid_form(&[laid_block()], 2, 2, &on_i(), &on_c(), ev(1, 2));
                assert_eq!(f.tensors.len(), kv["ntensors"].parse::<usize>().unwrap());
                let want = es(kv["out"]);
                let mut got = vec![E::zero(); want.len()];
                f.add_to(&mut got, 4);
                assert_eq!(got, want);
            }
            "BAT_LAYOUT" => {
                let (mut s, _g) = bat_setup();
                let inrun = s.begin_run(_g);
                bat_k = inrun.layout.k;
                assert_eq!(bat_k, kv["k"].parse::<u32>().unwrap());
                assert_eq!(inrun.layout.h, kv["h"].parse::<u32>().unwrap());
                assert_eq!(inrun.layout.members.len(), kv["members"].parse::<usize>().unwrap());
                assert_eq!(inrun.layout.members.len(), kv["kept_rows"].parse::<usize>().unwrap());
            }
            "BAT_TARGET" => {
                let (mut s, g) = bat_setup();
                let inrun = s.begin_run(g);
                let gr = bat::combine(&s, g, inrun, ev(8, 0));
                assert_eq!(gr.target, e(kv["t"]));
                assert_eq!(gr.group, kv["group"].parse::<u32>().unwrap());
                assert_eq!(gr.d, es(kv["d"]));
                assert_eq!(gr.kept.len(), kv["nkept"].parse::<usize>().unwrap());
                bat_gr = Some(gr);
            }
            "BAT_AT" => {
                let gr = bat_gr.as_ref().unwrap();
                let j: u64 = kv["j"].parse().unwrap();
                assert_eq!(gr.c.at(j), e(kv["v"]));
            }
            "BAT_ADD" => {
                let gr = bat_gr.as_ref().unwrap();
                let want = es(kv["out"]);
                let mut got = vec![E::zero(); want.len()];
                gr.c.add_to(&mut got, bat_k + 2);
                assert_eq!(got, want);
            }
            "BAT_SIGMA" => {
                let lone = {
                    let mut r = Row::plain("");
                    r.target = ev(9, 0);
                    r.add_unit(0, Part::Main, 1, ev(9, 2));
                    r
                };
                let combined = bat::combine_rows(&[lone], ev(9, 1), "combined");
                assert_eq!(combined.target, e(kv["target"]));
                assert_eq!(combined.terms.len(), kv["nterms"].parse::<usize>().unwrap());
                assert_eq!(combined.units.len(), kv["nunits"].parse::<usize>().unwrap());
            }
            "BATT_K" => {
                batt_rows = make_batt_rows();
                assert_eq!(batt_k_col(&batt_rows), kv["k_col"].parse::<u32>().unwrap());
                assert_eq!(batt_masks(batt_k_col(&batt_rows)), kv["masks"].parse::<usize>().unwrap());
            }
            "BATT_CLAIM" => {
                batt_rows = make_batt_rows();
                let bc = batt_claim(&mut batt_rows, ev(12, 0));
                assert_eq!(bc.chi, es(kv["chi"]));
                assert_eq!(bc.claim.target, e(kv["target"]));
                assert_eq!(bc.claim.vars.len(), kv["vars"].parse::<usize>().unwrap());
                assert_eq!(bc.summand.kept, kv["kept"].parse::<u32>().unwrap());
                assert_eq!(bc.summand.shown, kv["shown"].parse::<u32>().unwrap());
                assert_eq!(bc.summand.degree, kv["degree"].parse::<u32>().unwrap());
            }
            "BATT_S" => {
                batt_rows = make_batt_rows();
                let bc = batt_claim(&mut batt_rows, ev(12, 0));
                let point = [ev(12, 1), ev(12, 2)];
                assert_eq!((bc.summand.at)(&point, &[]), es(kv["at"]));
            }
            "BATT_G" => {}
            "BATT_ROW" => {
                batt_rows = make_batt_rows();
                let mut ledger = MaskLedger::new(receipt_for_a_test(0, 0, 8, 1, 0));
                let point = vec![ev(12, 1), ev(12, 2)];
                let out = PscOutput {
                    point: point.clone(),
                    row_masks: vec![MaskTerm { slot: ledger.take(), coeff: ev(13, 0) }],
                    row_maps: vec![KeptTerm { map: 0, coeff: ev(13, 1) }],
                    row_target: ev(13, 2),
                    ends: Vec::new(),
                };
                let br = batt_row(&batt_rows, out);
                assert_eq!(br.psi, es(kv["psi"]));
                assert_eq!(br.target, e(kv["target"]));
                assert_eq!(br.g.len(), kv["ng"].parse::<usize>().unwrap());
                assert_eq!(br.masks.len(), kv["masks"].parse::<usize>().unwrap());
                for (i, g) in br.g.iter().enumerate() {
                    let l = VECTORS
                        .lines()
                        .find(|l| l.starts_with(&format!("BATT_G i={} ", i)))
                        .unwrap();
                    let k = fields(l);
                    assert_eq!(g.vars(), k["vars"].parse::<u32>().unwrap());
                    for (j, want) in es(k["at"]).iter().enumerate() {
                        assert_eq!(g.at(j as u64), *want);
                    }
                }
            }
            "PSC_SIZE" => {
                let (claim, s, _ledger) = psc_setup();
                let vars = psc_vars(&claim, &s);
                assert_eq!(psc_masks(&claim, &s), kv["masks"].parse::<usize>().unwrap());
                assert_eq!(vars.len(), kv["vars"].parse::<usize>().unwrap());
            }
            "PSC_POINT" => {
                psc_out = Some(run_psc());
                assert_eq!(psc_out.as_ref().unwrap().point, es(line.split_whitespace().nth(1).unwrap()));
            }
            "PSC_ROW_TARGET" => {
                let out = psc_out.as_ref().unwrap();
                assert_eq!(out.row_target, e(line.split_whitespace().nth(1).unwrap()));
            }
            "PSC_ROW_MASKS" => {
                let out = psc_out.as_ref().unwrap();
                let txt = line.split_whitespace().nth(1).unwrap();
                let parts: Vec<&str> = if txt == "-" { Vec::new() } else { txt.split(';').collect() };
                assert_eq!(out.row_masks.len(), parts.len());
                for (i, p) in parts.iter().enumerate() {
                    let (o, idx, c) = mask_term(p);
                    assert_eq!(out.row_masks[i].slot.oracle(), o);
                    assert_eq!(out.row_masks[i].slot.index(), idx);
                    assert_eq!(out.row_masks[i].coeff, c);
                }
            }
            "PSC_ROW_MAPS" => {
                let out = psc_out.as_ref().unwrap();
                let txt = line.split_whitespace().nth(1).unwrap();
                let parts: Vec<&str> = if txt == "-" { Vec::new() } else { txt.split(';').collect() };
                assert_eq!(out.row_maps.len(), parts.len());
                for (i, p) in parts.iter().enumerate() {
                    let (m, coeff) = p.split_once(',').unwrap();
                    assert_eq!(out.row_maps[i].map, m.parse::<u32>().unwrap());
                    assert_eq!(out.row_maps[i].coeff, e(coeff));
                }
            }
            "PSC_ENDS" => {
                let out = psc_out.as_ref().unwrap();
                assert_eq!(out.ends.len(), kv["n"].parse::<usize>().unwrap());
            }
            "PSC_END" => {
                let out = psc_out.as_ref().unwrap();
                let i: usize = kv["i"].parse().unwrap();
                assert_eq!(out.ends[i].value, e(kv["value"]));
                assert_eq!(out.ends[i].point, es(kv["point"]));
                // The mask list is on the same line after `masks=`.
                let txt = kv["masks"];
                let parts: Vec<&str> = if txt == "-" { Vec::new() } else { txt.split(';').collect() };
                assert_eq!(out.ends[i].masks.len(), parts.len());
                for (j, p) in parts.iter().enumerate() {
                    let (o, idx, c) = mask_term(p);
                    assert_eq!(out.ends[i].masks[j].slot.oracle(), o);
                    assert_eq!(out.ends[i].masks[j].slot.index(), idx);
                    assert_eq!(out.ends[i].masks[j].coeff, c);
                }
            }
            other => panic!("line {}: unknown tag {}", lines, other),
        }
    }
    assert!(lines > 30 && mask_i == 4);
}

fn laid_block() -> LaidBlock {
    LaidBlock {
        first_i: 0,
        first_c: 0,
        first_row: 0,
        first_place: 0,
        bits_i: 1,
        bits_c: 1,
        row_bits: 1,
        place_bits: 1,
        i_is_low: true,
    }
}
fn on_i() -> IndexWeights {
    IndexWeights::powers(ev(1, 0), 1)
}
fn on_c() -> IndexWeights {
    IndexWeights::powers(ev(1, 1), 1)
}

fn bat_setup() -> (Statement, u32) {
    use fp_core::iop::relation::OracleId;
    let codes = Codes {
        base: vec![Code { log_n: 4, ell: 4, r: 2 }],
        mask: vec![Code { log_n: 2, ell: 2, r: 1 }],
    };
    let mut s = Statement::new(codes);
    let sh = OracleShape {
        name: String::from("oracle"),
        code: 0,
        main_rows: 2,
        main_deg: 1,
        mask_rows: 2,
        mask_code: 0,
        answers: 1,
    };
    let o: OracleId = s.sent(sh);
    let mut srow = Row::plain("r");
    srow.target = ev(4, 0);
    srow.add_unit(o, Part::Main, 0, ev(4, 1));
    s.sampled(
        &SendAccess,
        o,
        vec![srow],
        Vec::new(),
        receipt_for_a_test(o, 0, 2, 2, 1),
    );
    let g = s.new_group("g", 0, 0);
    s.join(g, o, false);
    let z = [ev(5, 0), ev(5, 1), ev(5, 4)];
    let pf = [fv(5, 2), fv(5, 3), fv(5, 5)];
    let mut r = Row::plain("r");
    r.add(o, Part::Main, fp_core::iop::tensor::Tensor::eq(&z, 3, ev(6, 0)));
    r.add(o, Part::Main, fp_core::iop::tensor::Tensor::product(&pf, 3, ev(6, 1)));
    r.add_unit(o, Part::Mask, 0, ev(6, 2));
    r.add_run(o, Part::Main, 0, 1, vec![ev(6, 3), ev(6, 4)]);
    r.target = ev(6, 5);
    s.add_row(g, r);
    let mut r2 = Row::plain("r2");
    r2.add_unit(o, Part::Main, 1, ev(7, 0));
    r2.target = ev(7, 1);
    s.add_row(g, r2);
    (s, g)
}

fn make_batt_rows() -> Vec<TensorRow> {
    let z = [ev(10, 0), ev(10, 1)];
    let pf = [fv(10, 2), fv(10, 3)];
    vec![
        TensorRow {
            g: vec![fp_core::iop::tensor::Tensor::eq(&z, 2, ev(11, 0))],
            psi: vec![ev(11, 1), ev(11, 2)],
            masks: Vec::new(),
            target: ev(11, 3),
        },
        TensorRow {
            g: vec![fp_core::iop::tensor::Tensor::product(&pf, 2, ev(11, 4))],
            psi: vec![ev(11, 5), ev(11, 6)],
            masks: Vec::new(),
            target: ev(11, 7),
        },
    ]
}

fn psc_setup() -> (SumClaim, Summand, MaskLedger) {
    let mut claim = SumClaim {
        vars: vec![
            fp_core::iop::hp::Weight::plain(2),
            fp_core::iop::hp::Weight::equality(ev(14, 0), 2),
            fp_core::iop::hp::Weight::at_zero(3),
        ],
        masks: Vec::new(),
        target: ev(14, 1),
    };
    let mut ledger = MaskLedger::new(receipt_for_a_test(1, 0, 32, 1, 0));
    claim.masks.push(MaskTerm { slot: ledger.take(), coeff: ev(14, 2) });
    let s = Summand {
        shown: 1,
        kept: 2,
        degree: 2,
        at: Box::new(|point: &[E], y: &[E]| {
            let mut a = vec![point[0] + y[0]];
            for i in 0..2 {
                a.push(point[(i + 1) % point.len()] + y[0]);
            }
            a
        }),
    };
    (claim, s, ledger)
}

fn run_psc() -> PscOutput {
    let (claim, s, mut ledger) = psc_setup();
    let vars = psc_vars(&claim, &s);
    let fresh = ledger.take_n(psc_masks(&claim, &s));
    let challenges = vec![ev(15, 0), ev(15, 1), ev(15, 2), ev(15, 3)];
    let ends = vec![ev(15, 4)];
    psc_rows(claim, &s, &vars, fresh, ev(15, 5), &challenges, ev(15, 6), &ends)
}
